mapper.select:
SELECT b.card_id
  FROM benefit b
 WHERE b.is_active = 'Y'
   AND b.benefit_kind NOT IN ('GIFT', 'INSTALLMENT_FREE', 'RETROACTIVE')
   AND (

            b.target_category_id IN

                #{categoryId}



            OR


            b.target_merchant_id IN

                #{merchantId}


       )

   AND b.card_id NOT IN

        #{cardId}


 GROUP BY b.card_id
 ORDER BY COUNT(*) DESC, b.card_id
 LIMIT #{limit}

SELECT b.card_id AS cardId, x.benefit_id, x.exclusion_type, x.exclusion_value FROM benefit_exclusion x JOIN benefit b ON b.benefit_id = x.benefit_id WHERE b.is_active = 'Y' AND b.benefit_kind NOT IN ('GIFT', 'INSTALLMENT_FREE', 'RETROACTIVE') AND b.card_id IN
#{cardId}
UNION ALL
SELECT b.card_id AS cardId, b.benefit_id, c.exclusion_type, c.exclusion_value FROM card_benefit_exclusion c JOIN benefit b ON b.card_id = c.card_id WHERE b.is_active = 'Y' AND b.benefit_kind NOT IN ('GIFT', 'INSTALLMENT_FREE', 'RETROACTIVE') AND c.card_id IN
#{cardId}

SELECT DISTINCT b.card_id AS cardId, b.option_group_code AS optionGroupCode, b.option_key AS optionKey FROM benefit b WHERE b.is_active = 'Y' AND b.option_group_code IS NOT NULL AND b.option_key IS NOT NULL AND b.benefit_kind NOT IN ('GIFT', 'INSTALLMENT_FREE', 'RETROACTIVE') AND b.card_id IN
#{cardId}
ORDER BY b.card_id, b.option_group_code, b.option_key
